import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Custom CUDA kernel for element-wise addition (replaces torch.add_elm or similar)
# ----------------------------------------------------------------------
elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
elementwise_add_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float()>, out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_cuda_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
# Custom CUDA kernel for cumulative product along a dimension
# ----------------------------------------------------------------------
cumprod_cpp_source = "torch::Tensor cumprod_cuda(torch::Tensor a, int dim);"
cumprod_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void cumprod_kernel(const float* a, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        // Compute prefix product up to this index.
        float prod = 1.0f;
        for (int j = 0; j <= idx; ++j) {
            prod *= a[j];
        }
        out[idx] = prod;
    }
}

torch::Tensor cumprod_cuda(torch::Tensor a, int dim) {
    auto size = a.numel();
    float* out_ptr = static_cast<float*>(a.data_ptr());
    torch::Tensor out_tensor = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    cumprod_kernel<<<num_blocks, block_size>>>(a.data_ptr<float()>, out_tensor.data_ptr<float()>, size);

    return out_tensor;
}
"""

cumprod_cuda = load_inline(
    name="cumprod_cuda",
    cpp_sources=cumprod_cpp_source,
    cuda_sources=cumprod_kernel_source,
    functions=["cumprod_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# ----------------------------------------------------------------------
# Optimized model that replaces torch.cumprod with the custom CUDA operator
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_add = elementwise_add   # not used in forward for cumprod, but kept for completeness
        self.cumprod_cuda = cumprod_cuda

    def forward(self, x):
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, *input_shape).
        Returns:
            torch.Tensor: Tensor of the same shape as `x` after applying cumulative product along `dim`.
        """
        return self.cumprod_cuda(x, self.dim)
